// One classifier for every Smartlead event we act on. Field names have
// drifted across API versions (docs vs blog disagree) so read every known
// spelling — the same defensive stance app/providers/smartlead.py takes.
//
// Two independent effects, each gated by its own output field:
//   reason    (non-empty) -> add the address to the suppression list
//   newStatus (non-empty) -> advance the contact's email_status
// A hard bounce does BOTH (suppress + mark bounced). A reply only marks
// (a reply is not a do-not-contact). Soft bounces / opens / clicks are
// ignored. Status writes NEVER move a contact backwards (see the SQL), so
// the at-most-one-send invariant holds — 'sent_email' only ever resolves
// a contact stuck at 'sending' on Smartlead's own send confirmation.
const b = $json.body ?? $json;

const type = String(b.event_type ?? b.event ?? '').toUpperCase();
const email = String(b.lead_email ?? b.lead?.email ?? b.to_email ?? b.email ?? '')
  .trim().toLowerCase();
const bounceType = String(b.bounce_type ?? b.bounce_category ?? '').toLowerCase();
const campaignId = String(b.campaign_id ?? b.email_campaign_id ?? b.campaignId ?? '').trim();

const isUnsub = type.includes('UNSUBSCRIB');
const isHardBounce = type.includes('BOUNCE') && bounceType === 'hard';
const isReply = type.includes('REPLY');
const isSent = type.includes('SENT');   // EMAIL_SENT / FIRST_EMAIL_SENT

let reason = '';      // -> suppression insert
let newStatus = '';   // -> contacts.email_status
let eventType = '';

if (isUnsub)          { reason = 'unsubscribed'; eventType = 'suppression_added'; }
else if (isHardBounce){ reason = 'hard_bounce'; newStatus = 'bounced'; eventType = 'bounce_suppressed'; }
else if (isReply)     { newStatus = 'replied'; eventType = 'reply_received'; }
else if (isSent)      { newStatus = 'sent_email'; eventType = 'send_confirmed'; }

const relevant = Boolean(email) && (reason !== '' || newStatus !== '');

return [{ json: { relevant, email, reason, newStatus, campaignId, eventType } }];
